using Microsoft.EntityFrameworkCore;

namespace HumanitarianCrisis.API.Data;

/// <summary>Creates the password-reset token table for databases initially created with EnsureCreated.</summary>
public static class PasswordResetSchema
{
    public static async Task EnsureAsync(CrisisDbContext db, CancellationToken cancellationToken = default)
    {
        var provider = db.Database.ProviderName ?? string.Empty;
        var sql = provider switch
        {
            "Microsoft.EntityFrameworkCore.SqlServer" => "IF OBJECT_ID(N'[dbo].[PasswordResetTokens]', N'U') IS NULL CREATE TABLE [dbo].[PasswordResetTokens] ([Id] int IDENTITY(1,1) NOT NULL PRIMARY KEY, [AccountId] int NOT NULL, [TokenHash] nvarchar(64) NOT NULL, [CreatedAt] datetime2 NOT NULL, [ExpiresAt] datetime2 NOT NULL, [UsedAt] datetime2 NULL, CONSTRAINT [FK_PasswordResetTokens_Accounts] FOREIGN KEY ([AccountId]) REFERENCES [dbo].[Accounts]([Id]) ON DELETE CASCADE); IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'IX_PasswordResetTokens_TokenHash') CREATE UNIQUE INDEX [IX_PasswordResetTokens_TokenHash] ON [dbo].[PasswordResetTokens] ([TokenHash]); IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'IX_PasswordResetTokens_AccountId_CreatedAt') CREATE INDEX [IX_PasswordResetTokens_AccountId_CreatedAt] ON [dbo].[PasswordResetTokens] ([AccountId], [CreatedAt]);",
            "Npgsql.EntityFrameworkCore.PostgreSQL" => "CREATE TABLE IF NOT EXISTS \"PasswordResetTokens\" (\"Id\" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, \"AccountId\" integer NOT NULL REFERENCES \"Accounts\"(\"Id\") ON DELETE CASCADE, \"TokenHash\" varchar(64) NOT NULL, \"CreatedAt\" timestamp with time zone NOT NULL, \"ExpiresAt\" timestamp with time zone NOT NULL, \"UsedAt\" timestamp with time zone NULL); CREATE UNIQUE INDEX IF NOT EXISTS \"IX_PasswordResetTokens_TokenHash\" ON \"PasswordResetTokens\" (\"TokenHash\"); CREATE INDEX IF NOT EXISTS \"IX_PasswordResetTokens_AccountId_CreatedAt\" ON \"PasswordResetTokens\" (\"AccountId\", \"CreatedAt\");",
            _ => "CREATE TABLE IF NOT EXISTS \"PasswordResetTokens\" (\"Id\" INTEGER NOT NULL CONSTRAINT \"PK_PasswordResetTokens\" PRIMARY KEY AUTOINCREMENT, \"AccountId\" INTEGER NOT NULL REFERENCES \"Accounts\" (\"Id\") ON DELETE CASCADE, \"TokenHash\" TEXT NOT NULL, \"CreatedAt\" TEXT NOT NULL, \"ExpiresAt\" TEXT NOT NULL, \"UsedAt\" TEXT NULL); CREATE UNIQUE INDEX IF NOT EXISTS \"IX_PasswordResetTokens_TokenHash\" ON \"PasswordResetTokens\" (\"TokenHash\"); CREATE INDEX IF NOT EXISTS \"IX_PasswordResetTokens_AccountId_CreatedAt\" ON \"PasswordResetTokens\" (\"AccountId\", \"CreatedAt\");"
        };

        await db.Database.ExecuteSqlRawAsync(sql, cancellationToken);
    }
}
